#include <vector>
#include <complex>
#include <algorithm>
#include <omp.h>

void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    const std::size_t n = x.size();
    if (n < 2) return;

    // Odd-even transposition sort (parallel-friendly, deterministic)
    // Comparator: ascending by magnitude (norm), then real, then imag for tie-break stability.
    for (std::size_t phase = 0; phase < n; ++phase) {
        const std::size_t start = phase % 2; // even phase: (0,1),(2,3)... ; odd phase: (1,2),(3,4)...

        #pragma omp parallel for default(none) shared(x, n, start)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(start);
             i + 1 < static_cast<std::ptrdiff_t>(n);
             i += 2) {
            auto &a = x[static_cast<std::size_t>(i)];
            auto &b = x[static_cast<std::size_t>(i + 1)];

            const double na = std::norm(a);
            const double nb = std::norm(b);

            bool shouldSwap = false;
            if (na > nb) {
                shouldSwap = true;
            } else if (na == nb) {
                if (a.real() > b.real()) {
                    shouldSwap = true;
                } else if (a.real() == b.real() && a.imag() > b.imag()) {
                    shouldSwap = true;
                }
            }

            if (shouldSwap) {
                std::swap(a, b);
            }
        }
    }
}
